export function InfiniteList({
  heading = "{{heading}}",
  accent = "{{accent}}",
  visibleCount = "{{visibleCount}}",
  loading = {{loading}},
  total = {{total}},
}) {
  const items = [
    "Priya updated the roadmap", "New comment on Q3 plan", "Marcus joined the workspace",
    "Budget approved", "Release 4.2 shipped", "Weekly digest sent",
    "Priya updated the roadmap", "New comment on Q3 plan",
  ].slice(0, Number(visibleCount));
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2", maxWidth: 320, width: 320, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 10px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, maxHeight: 220, overflow: "auto" }}>
        {items.map((item, i) => (
          <li key={i} style={{ padding: "8px 10px", borderBottom: "1px solid #24143014", borderLeft: `3px solid ${accent}`, marginBottom: 4, background: "#fff", borderRadius: "0 6px 6px 0" }}>{item}</li>
        ))}
      </ul>
      <p role="status" style={{ margin: "10px 0 0", fontSize: 12, color: "#241430a0", textAlign: "center" }}>
        {loading ? "Loading more items…" : `Showing ${visibleCount} of ${total} items — scroll to load more.`}
      </p>
    </div>
  );
}
